import React, { useState } from 'react';
import {
  BrowserRouter as Router,
  Routes,
  Route,
  Link
} from 'react-router-dom';
import SurveyForm from './components/SurveyForm';
import FeedbackForm from './components/FeedbackForm';
import FeedbackList from './components/FeedbackList';
import AdminPanel from './components/AdminPanel';
import LoginPage from './components/LoginPage';
import StatisticsDashboard from './components/StatisticsDashboard';
import ChoiceStatistics from './components/ChoiceStatistics';
import StatisticsViewer from './components/StatisticsViewer';

function HomePage({ onFeedbackSent, reloadFlag }) {
  const [selectedQuestion, setSelectedQuestion] = useState('');
  const [questions, setQuestions] = useState([
    { id: 1, question_text: 'Как вы оцениваете качество сервиса?' },
    { id: 2, question_text: 'Насколько вам нравится интерфейс сайта?' }
  ]);

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-100 to-purple-100 p-6 font-sans">
      <div className="max-w-4xl mx-auto bg-white rounded-2xl shadow-xl p-8">
        <h1 className="text-4xl font-bold mb-4 text-center text-indigo-600">EchoPoll</h1>
        <p className="text-lg text-gray-700 mb-6 text-center">Поделитесь своим мнением! Анонимно. Быстро. Важно.</p>

        <div className="grid md:grid-cols-1 gap-6">
          <div className="bg-gray-50 p-4 rounded-lg shadow-sm">
            <h2 className="text-xl font-semibold text-indigo-500 mb-2">Пройти опрос</h2>
            <SurveyForm />
          </div>

          <div className="bg-gray-50 p-4 rounded-lg shadow-sm">
            <h2 className="text-xl font-semibold text-indigo-500 mb-2">Оставить отзыв</h2>
            <FeedbackForm onFeedbackSent={onFeedbackSent} />
          </div>
        </div>

        <div className="mt-8">
          <h2 className="text-xl font-semibold text-indigo-500 mb-2">Отзывы</h2>
          <FeedbackList reloadFlag={reloadFlag} />
        </div>

        {/* Кастомный Select */}
        <div className="mt-8">
          <label id="listbox-label" className="block text-sm font-medium text-gray-900 mb-2">Выберите вопрос</label>
          <div className="relative">
            <button
              type="button"
              className="grid w-full cursor-default grid-cols-1 rounded-md bg-white py-2 pr-3 pl-4 text-left text-gray-900 outline-1 focus:outline-none focus:ring-2 focus:ring-indigo-600"
              aria-haspopup="listbox"
              aria-expanded={selectedQuestion ? "true" : "false"}
              aria-labelledby="listbox-label"
              onClick={() => setSelectedQuestion('')}>
              <span className="flex items-center gap-3">
                <span className="block truncate">{selectedQuestion || "Выберите вопрос"}</span>
              </span>
              <svg className="w-5 h-5 text-gray-500" viewBox="0 0 20 20" fill="currentColor" aria-hidden="true">
                <path fillRule="evenodd" d="M5.22 10.22a.75.75 0 0 1 1.06 0L8 11.94l1.72-1.72a.75.75 0 1 1 1.06 1.06l-2.25 2.25a.75.75 0 0 1-1.06 0l-2.25-2.25a.75.75 0 0 1 0-1.06ZM10.78 5.78a.75.75 0 0 1-1.06 0L8 4.06 6.28 5.78a.75.75 0 0 1-1.06-1.06l2.25-2.25a.75.75 0 0 1 1.06 0l2.25 2.25a.75.75 0 0 1 0 1.06Z" clipRule="evenodd" />
              </svg>
            </button>
            {/* Список опций */}
            <ul
              className={`absolute z-10 mt-1 w-full max-h-56 overflow-auto rounded-md bg-white py-1 text-base shadow-lg ring-1 ring-black/5 focus:outline-none sm:text-sm ${selectedQuestion ? 'block' : 'hidden'}`}
              role="listbox"
              aria-labelledby="listbox-label">
              {questions.map((question) => (
                <li
                  key={question.id}
                  className="relative cursor-pointer py-2 pl-4 pr-9 text-gray-900 select-none hover:bg-indigo-600 hover:text-white"
                  role="option"
                  onClick={() => setSelectedQuestion(question.question_text)}>
                  <span className="block truncate">{question.question_text}</span>
                  {selectedQuestion === question.question_text && (
                    <span className="absolute inset-y-0 right-0 flex items-center pr-4 text-indigo-600">
                      <svg className="w-5 h-5" viewBox="0 0 20 20" fill="currentColor" aria-hidden="true">
                        <path fillRule="evenodd" d="M16.704 4.153a.75.75 0 0 1 .143 1.052l-8 10.5a.75.75 0 0 1-1.127.075l-4.5-4.5a.75.75 0 0 1 1.06-1.06l3.894 3.893 7.48-9.817a.75.75 0 0 1 1.05-.143Z" clipRule="evenodd" />
                      </svg>
                    </span>
                  )}
                </li>
              ))}
            </ul>
          </div>
        </div>

        <div className="mt-6 flex justify-center space-x-4">
          <Link to="/statistics" className="bg-indigo-600 text-white px-6 py-2 rounded-full shadow hover:bg-indigo-700 transition">
            Перейти к статистике
          </Link>
          <Link to="/login" className="text-indigo-600 underline hover:text-indigo-800 transition">
            Вход для администратора
          </Link>
        </div>
      </div>
    </div>
  );
}

function App() {
  const [reloadFlag, setReloadFlag] = useState(false);

  const handleFeedbackSent = () => {
    setReloadFlag(!reloadFlag);
  };

  return (
    <Router>
      <Routes>
        <Route
          path="/"
          element={<HomePage onFeedbackSent={handleFeedbackSent} reloadFlag={reloadFlag} />}
        />
        <Route path="/stats" element={<StatisticsDashboard />} />
        <Route path="/login" element={<LoginPage />} />
        <Route path="/admin" element={<AdminPanel />} />
        <Route path="/stats/choices/:questionId" element={<ChoiceStatistics />} />
        <Route path="/statistics" element={<StatisticsViewer />} />
      </Routes>
    </Router>
  );
}

export default App;
